mapper.select:
SELECT regNum, p_Name, p_guardian, title, p_content, regDate, p_pwd, viewCnt
FROM pet_free_board
WHERE regNum = #{regNum}

mapper.update:
UPDATE pet_free_board
SET viewCnt = viewCnt + 1
WHERE regNum = #{regNum}

UPDATE pet_free_board
SET p_Name = #{pName},
p_guardian = #{pGuardian},
title = #{title},
p_content = #{pContent}
WHERE regNum = #{regNum}
